where.if:
and exists (
    select 1
    from fx67ll_dortmund_return_combination_item mi
    where mi.combination_id = c.combination_id
      and mi.match_id = #{matchId}
)

mapper.select:
select count(1)
from fx67ll_dortmund_plan_return_rel
where combination_id = #{combinationId}

select count(1)
from fx67ll_dortmund_return_combination
where generation_id = #{generationId}
